   [5]={next_id=6, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="围栏将大楼团团围住，只留下正门一个出入口。穿黑色制服的安保人员警戒在四周，盾牌和橡胶棍在路灯下反射着冷硬的光。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_310.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
